style.css:
@-moz-document domain("youtube.com") {
/* Your Cutesy Vintage YouTube Theme */
    
    :root {
        -background-color: #fdf6e3;
        -text-color: #5e4b56;
        -accent-color: #f3a4b5;
        -button-color: #f7d9c4;
        -border-radius: 15px;
        -font-family: 'Courier New', cursive;
    }

    body {
        background-color: var(--background-color) !important;
        font-family: var(--font-family) !important;
        color: var(--text-color) !important;
    }

    /* Header */
    #masthead-container {
        background-color: var(--accent-color) !important;
        border-bottom: 3px solid var(--text-color) !important;
    }

    /* Sidebar */
    #guide-content {
        background-color: var(--background-color) !important;
        border-right: 2px dashed var(--accent-color) !important;
    }

    /* Video Titles */
    h1, h2, h3, h4, h5, h6 {
        font-family: var(--font-family) !important;
        color: var(--text-color) !important;
    }

    /* Video Thumbnails */
    .ytd-thumbnail {
        border-radius: var(--border-radius) !important;
        box-shadow: 3px 3px 10px rgba(0, 0, 0, 0.1) !important;
    }

    /* Buttons */
    button, .ytp-button {
        background-color: var(--button-color) !important;
        border-radius: var(--border-radius) !important;
        border: 2px solid var(--text-color) !important;
    }

    button:hover, .ytp-button:hover {
        background-color: var(--accent-color) !important;
    }

    /* Video Player */
    .html5-video-container {
        border-radius: var(--border-radius) !important;
    }

    /* Comments Section */
    #comments {
        background-color: var(--background-color) !important;
        border-top: 2px solid var(--accent-color) !important;
        padding: 10px !important;
        border-radius: var(--border-radius) !important;
    }
}
